        for k, pairs in edge_points.items():
            uf.union(pairs)
            for i, j in edges:
                if uf.find(i) != uf.find(j):
                    edges.append((k - (a[i] + a[j]), i, j))
        edges.sort(reverse=True)
        path, distances, vis = deque(), [float('inf')] * n, [False] * n
        path.append((0, nodes[0]))
        vis[nodes[0]] = True
        for dist, i, j in edges:
            if not vis[j]:
                path.append((dist, j))
                vis[j] = True
                distances[j] = dist
        for i in range(1, n):
            print(path[i][1], path[i][0] - path[i - 1][0])
        print(sum(distances))

class UnionFind:
    def __init__(self, n):
        self.parents = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if x != self.parents[x]:
            self.parents[x] = self.find(self.parents[x])
        return self.parents[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr != yr:
            if self.rank[xr] > self.rank[yr]:
                self.parents[yr] = xr
            else:
                self.parents[xr] = yr
                self.rank[yr] += 1

