def bfs(x0, y0, k):
    return min(q[0] for q in dfs([(x0, 0, 0, 0)], ((x0, 0), (0, y0)), k))

def dfs(memo, nodes, k, pos=[], time=0, carrying=0):
    if not nodes and pos:
        memo.append((time, pos))
        return time

    for (nx, act) in nodes:
        if not pos or pos[-1][0] != nx:
            act_time = time + abs(pos[-1][0] - nx)
            if act == "T" and carrying + 1 <= k:
                dfs(memo, nodes, k, pos + ((-nx, nx),), act_time, carrying + 1)
            if act == "K":
                if pos and pos[-1][1] == nx and (carrying == 0 or pos[-1][3] == -nx):
                    if not memo:
                        memo.append((act_time, pos + ((-nx, nx),)))
                    else:
                        for m in memo:
