                                memo.insert(0, (act_time, pos + ((-nx, nx),)))
                                break
                dfs(memo, nodes, k, pos + ((-nx, nx),), act_time)

    nodes = [(q, 'T') for q, _ in nodes if q != (-x0, y0)]
    nodes = [(q, 'K') for q in nodes if q[0] == x0]
    nodes = deque(nodes)
    return memo

