import heapq

def solve(arr):
    n = len(arr)
    if n == 0:
        return 'NO'
    elif n == 1:
        return 'YES'

    heap = arr[:]
    for i in range(n, -1, 2**-1):
        if i <= n:
            h = len(heap)
            while h > i:
                heapq.heappop(heap)
                h -= 1
            for j in range(i):
                heapq.heappush(heap, arr[j])
            for j in range(i-1, -1, -1):
                arr[j+1] = heapq.heappop(heap)

    for i in range(1, n):
        if arr[i] < arr[i-1]:
            return 'NO'
    return 'YES'

