from functools import reduce, lru_cache

@lru_cache(maxsize=None)
def binary_or(x, y):
    return x | y

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        operation = binary_or(*(1 << i for i in range(n) if a[i] > a[(i + 1) % n]))
        while operation != 0:
            for i in range(n - 1):
                if (operation & (1 << i)) > 0 and (operation & (1 << (i + 1))) > 0 and a[i] > a[i + 1]:
                    a[i], a[i + 1] = a[i + 1], a[i]
            operation = binary_or(*(1 << i for i in range(n) if (a[i] > a[(i + 1) % n])))
        print("YES" if reduce(binary_or, a[1:], a[0] > a[1]) else "NO")

solve()
```

