import itertools
import math

def sieve(limit):
    primes = [True] * (limit + 1)
    primes[0], primes[1] = False, False
    for i in range(2, int(math.sqrt(limit)) + 1):
        if primes[i]:
            for j in range(i * i, limit + 1, i):
                primes[j] = False
    return [2] + [i for i in range(3, limit + 1) if primes[i]]

primes = sieve(1e5)

def solve(n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def find_next(current_val, factors):
        for i, prime in enumerate(primes):
            if prime > math.sqrt(current_val) or current_val % prime:
                continue
            factor = 1
            power = 0
            while current_val % prime:
                power += 1
                current_val -= factor * prime
                factor *= prime
            if power % 2 == 1:
                continue
            factor //= prime
            if current_val < factor:
                return factor
            if not factors:
                factors.append((prime, power))
            else:
                prev_prime, prev_power = factors[-1]
                if lcm(prime, prev_prime) <= current_val:
                    factors[-1] = (prime, min(prev_power, power))
                    return factor
                else:
                    factors.append((prime, power))
        return None

    if n == 3:
        return [2, 3, 5]
    else:
        ans = [2]
        factors = []
        for i in range(2, n - 1):
            next_val = ans[-1] + ans[-2] + 2
            next_val = find_next(next_val, factors)
            ans.append(next_val)
        return ans

