import sys

def sieve(max_val):
    sieve = [1 for _ in range(max_val+1)]
    for p in range(2, max_val+1):
        if sieve[p] == 1:
            for i in range(p*p, max_val+1, p):
                sieve[i] = 0
    return sieve

def solve(n, k, x):
    m = len(sieve)
    sieve.extend([0] + sieve[:m-1])
    dp = [0] * (n+1)
    if n == 1:
        return x
    for i in range(1, n+1):
        for j in range(i, min(m, k)+1):
            dp[i] = max(dp[i], dp[i-j] + j)
        dp[i] = min(dp[i], x)
    for i in range(n, 0, -1):
        for j in range(m-1, k-1, -1):
            if dp[i] < x:
                dp[i-sieve[j]] = max(dp[i-sieve[j]], dp[i]+j)
        dp[i] = min(dp[i], x)
    return dp[n] if dp[n] <= x else -1

