import sys
from collections import defaultdict
import functools

inf = float('inf')

def dijkstra(graph, start):
    distances = defaultdict(lambda: inf)
    distances[start] = 0
    visited = set()

    while len(visited) < len(graph):
        u = min(graph, key=distances.get)
        visited.add(u)
        for v, w in graph[u].items():
            if v not in visited and distances[u] + w < distances[v]:
                distances[v] = distances[u] + w

    return distances

def solve():
    n, *buttons = map(int, sys.stdin.readline().strip().split())
    graph = defaultdict(lambda: defaultdict(lambda: inf))
    for i, a in enumerate(buttons[:n]):
        for j, k in enumerate(buttons[n:]):
            if i != j:
                graph[i][j] = 1
    Anna_dist = dijkstra(graph, n)
    Katie_dist = dijkstra(graph, n + n)

    # flip the distances for Katie's view
    for u in range(n, 2*n):
        for v in range(n, 2*n):
            if u != v:
                Katie_dist[u][v] = min(Katie_dist[u][v], graph[u - n][v - n])

    # if there is a button Anna can reach, but Katie can't, Anna wins
    for i in range(n, 2*n):
        if Anna_dist[i] < Katie_dist[i]:
            return 'First'

    # if there is a button Katie can reach, but Anna can't, Katie wins
    for i in range(n, 2*n):
        if Katie_dist[i] < Anna_dist[i]:
            return 'Second'

    # if no button can be reached by either, the game is a draw
    return 'Draw'

for _ in range(int(sys.stdin.readline())):
