import math
from collections import defaultdict

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    parents = list(range(n))
    ranks = [0]*n
    total = sum(a)

    def find(i):
        if parents[i]!=i:
            parents[i] = find(parents[i])
        return parents[i]

    def union(i, j):
        i, j = find(i), find(j)
        if i == j:
            return
        if ranks[i] > ranks[j]:
            parents[j] = i
            ranks[i] += ranks[j]
        else:
            parents[i] = j
            ranks[j] += ranks[i]

    def get_max_diff():
        total_sum = 0
        sizes = [0]*n
        for i in range(n):
            root = find(i)
            sizes[root] += a[i]
            total_sum += a[i]
        sizes.sort(reverse=True)
        size_set = defaultdict(int)
        maxlen = 0
        for size in sizes:
            size_set[size] += 1
            if size_set[size] == sizes.count(size):
                maxlen = max(maxlen, size)
        return abs(maxlen * total - total_sum + maxlen)

    for i in range(n):
        for j in range(i+1, n):
            union(i, j)
    return get_max_diff()

