def is_valid_perm(n, p):
    neighbors = defaultdict(set)
    for i in range(n):
        left = (i-1) % n
        right = (i+1) % n
        if p[i] - 1 != p[left] and p[i] + 1 != p[right]:
            return False
        neighbors[p[i]].add(i)

    for num in range(1, n+1):
        if not neighbors[num]:
            return False

    return True

def make_permutation(n):
    if n <= 1:
        return [1]
    visited = [False] * n
    graph = defaultdict(list)
    dfs(0, n, visited, graph)
    permutation = deque()
    for i in range(n):
        permutation.append(graph[i][0])
        visited[graph[i][0]] = True

    while permutation:
        current = permutation.popleft()
        neighbors = graph[current]
        assert len(neighbors) == 1, "Graph is not connected"
        neighbors = neighbors[0]
        next_node = neighbors[1] if neighbors[0] - 1 == current else neighbors[0] - 2
        permutation.appendleft(next_node)
        visited[next_node] = True

    assert all(visited), "Fixed point detected"
    return list(permutation)

