import sys
from functools import lru_cache

def solve():
    n, m = map(int, sys.stdin.readline().strip().split())
    @lru_cache((n, m, n - 1, m - 1))
    def dp(i, j, x, y):
        if not (i <= x and j <= y):
            return float('inf')
        if i == x and j == y:
            return 0
        return min(dp(i + 1, j, x, y) + (i - 1) * m, dp(i, j + 1, x, y) + (i - 1) * m + j)

    return dp(1, 1, n - 1, m - 1)

def main():
